"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  galleryStyle,
  galleryWrap,
  useGalleryEnvironment,
  useGalleryMotion,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface InfiniteMarqueeItem extends GalleryInternalItem {}
export interface InfiniteMarqueeProps extends GalleryInternalProps {
  items: readonly InfiniteMarqueeItem[];
  direction?: "left" | "right" | "up" | "down";
  speed?: number;
  gap?: number;
  /** Number of opposing lanes for horizontal motion. Vertical motion uses one column. */
  rows?: number;
  drag?: boolean;
  autoplay?: boolean;
  pauseOnHover?: boolean;
  angle?: number;
  fontSize?: number;
  renderItem?: (item: InfiniteMarqueeItem, index: number) => ReactNode;
}
/** Measured content repeats at its exact width or height, allowing either axis to wrap seamlessly. */
export function InfiniteMarquee({
  items,
  direction = "left",
  speed = 65,
  gap = 40,
  rows = 2,
  drag = true,
  autoplay = true,
  pauseOnHover = false,
  angle = -3,
  fontSize = 88,
  renderItem,
  index,
  defaultIndex,
  onChange,
  onSelect,
  height = 640,
  label = "Infinite marquee",
  className = "",
  style,
}: InfiniteMarqueeProps) {
  const env = useGalleryEnvironment();
  const vertical = direction === "up" || direction === "down";
  const group = useRef<HTMLDivElement>(null);
  const [extent, setExtent] = useState(2000);
  const sign = direction === "right" || direction === "down" ? -1 : 1;
  const motion = useGalleryMotion(
    items.length,
    {
      index,
      defaultIndex,
      onChange,
      drag,
      autoplay,
      speed: (speed * sign * items.length) / extent,
      sensitivity: extent / Math.max(1, items.length),
      vertical,
      pauseOnHover,
    },
    env,
  );
  const selection = motion.current;
  const offset = (motion.phase * extent) / Math.max(1, items.length);
  useEffect(() => {
    const el = group.current;
    if (!el) return;
    const measure = () => {
      const measured = vertical ? el.offsetHeight : el.offsetWidth;
      // Hidden ancestors report zero; keep the last usable size until layout returns.
      if (Number.isFinite(measured) && measured > 0) setExtent(measured);
    };
    measure();
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(measure);
    observer?.observe(el);
    return () => observer?.disconnect();
  }, [vertical, items, gap, fontSize]);
  const copies = Math.max(3, Math.ceil((vertical ? env.size.height : env.size.width) / extent) + 2);
  return (
    <div
      ref={env.ref}
      {...motion.handlers}
      className={`z-ag ${className}`}
      data-gallery="infinite-marquee"
      data-index={selection}
      data-phase={motion.phase.toFixed(3)}
      tabIndex={0}
      role="region"
      aria-label={label}
      style={galleryStyle(height, {
        userSelect: drag ? "none" : undefined,
        touchAction: drag ? (vertical ? "pan-x" : "pan-y") : undefined,
        cursor: drag ? "grab" : undefined,
        ...style,
      })}
    >
      <GalleryInternalStyles />
      <div
        style={{
          position: "absolute",
          width: vertical ? undefined : "100%",
          height: vertical ? "100%" : undefined,
          display: "flex",
          flexDirection: vertical ? "row" : "column",
          gap: gap / 2,
          left: vertical ? "50%" : 0,
          top: vertical ? 0 : "50%",
          transform: vertical
            ? `translateX(-50%) rotate(${angle}deg)`
            : `translateY(-50%) rotate(${angle}deg)`,
        }}
      >
        {Array.from(
          { length: vertical ? 1 : Math.max(1, Math.min(3, Math.round(rows))) },
          (_, lane) => (
            <div
              key={lane}
              aria-hidden={lane > 0 ? true : undefined}
              className="z-ag-marquee-track"
              style={{
                display: "flex",
                flexDirection: vertical ? "column" : "row",
                width: "max-content",
                transform: `translate${vertical ? "Y" : "X"}(${-galleryWrap(lane % 2 ? -offset + extent * 0.2 : offset, extent)}px)`,
              }}
            >
              {Array.from({ length: copies }, (_, copy) => (
                <div
                  key={copy}
                  ref={copy === 0 && lane === 0 ? group : undefined}
                  aria-hidden={copy > 0 ? true : undefined}
                  style={{
                    display: "flex",
                    flexDirection: vertical ? "column" : "row",
                    alignItems: "center",
                    gap,
                    paddingRight: vertical ? 0 : gap,
                    paddingBottom: vertical ? gap : 0,
                    flexShrink: 0,
                  }}
                >
                  {items.map((item, i) => (
                    <button
                      type="button"
                      key={item.id}
                      tabIndex={copy === 0 && lane === 0 ? 0 : -1}
                      aria-label={item.title}
                      onClick={(event) => {
                        if (event.detail === 0 || !motion.moved.current) onSelect?.(item, i);
                      }}
                      style={{
                        display: "flex",
                        flexDirection: vertical ? "column" : "row",
                        gap: vertical ? gap / 2 : gap,
                        alignItems: "center",
                        border: 0,
                        padding: 0,
                        background: "none",
                        whiteSpace: "nowrap",
                        fontSize: `clamp(38px,7vw,${fontSize}px)`,
                        fontWeight: 800,
                        letterSpacing: "-.06em",
                        flexShrink: 0,
                        cursor: "pointer",
                      }}
                    >
                      {renderItem ? (
                        renderItem(item, i)
                      ) : (
                        <>
                          <span>{item.title?.toUpperCase()}</span>
                          {(item.src || item.content) && (
                            <GalleryInternalImage
                              item={item}
                              style={{
                                width: Math.min(155, env.size.width * 0.28),
                                height: Math.min(110, env.size.width * 0.2),
                                borderRadius: 6,
                                flexShrink: 0,
                              }}
                            />
                          )}
                        </>
                      )}
                    </button>
                  ))}
                </div>
              ))}
            </div>
          ),
        )}
      </div>
      {autoplay && (
        <button
          data-gallery-control
          type="button"
          aria-label={motion.paused ? "Play animation" : "Pause animation"}
          aria-pressed={motion.paused}
          onClick={() => motion.setPaused(!motion.paused)}
          style={{
            position: "absolute",
            right: 24,
            bottom: 24,
            width: 40,
            height: 40,
            border: 0,
            borderRadius: 6,
            background: "#d5d4d1",
          }}
        >
          {" "}
          {motion.paused ? "▷" : "Ⅱ"}{" "}
        </button>
      )}
    </div>
  );
}
